package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=33,qualifiers="w360dp-h720dp-mdpi",application=Application.class)
@LooperMode(LooperMode.Mode.PAUSED)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class BooksToolsTest {
 ActivityController<MainActivity> controller;MainActivity a;BookLibrary b;
 @Before public void setup(){controller=Robolectric.buildActivity(MainActivity.class);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);a.prefs=a.getSharedPreferences("seeky",0);a.colors();a.tab="Livros";a.thumbnails=new Thumbnails(a);a.body=a.column();a.body.setBackgroundColor(a.bg);a.setContentView(a.body);b=new BookLibrary(a);a.books=b;}
 void drain()throws Exception{b.worker.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}
 long material(String title,int percent){try(StudyStore store=new StudyStore(a)){return store.save("materials",0,StudyStore.values("subject",0,"title",title,"author","Autor de teste","name",title+".txt","mime","text/plain","path","/private/test","hash",UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-",""),"bytes",24,"progress",percent,"status",percent==100?"Concluído":percent==0?"Por estudar":"A estudar","created",1,"updated",1));}}
 @After public void close(){b.close();a.thumbnails.close();UiDialog.dismissAll(a);UiPanel.dismissAll(a);a.dead=true;a.worker.shutdown();a.finder.shutdown();a.searchJobs.close();}
 @Test public void shelfDrawsPercentageOnEachCoverAndFiltersWithoutChangingMaterials()throws Exception{material("Fé e conhecimento",7);material("A arte de ler",38);material("Cursos e módulos",100);b.show();drain();assertEquals(3,b.books.size());assertEquals(3,count(a.body,BookProgressBadge.class));for(int mode=0;mode<3;mode++){b.mode=mode;b.draw();a.body.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(650,View.MeasureSpec.EXACTLY));a.body.layout(0,0,360,650);Bitmap bitmap=Bitmap.createBitmap(360,650,Bitmap.Config.ARGB_8888);a.body.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-books-"+mode+".png")){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}assertEquals(3,count(a.body,BookProgressBadge.class));}b.mask=4;b.reload();drain();assertEquals(1,b.books.size());try(StudyStore store=new StudyStore(a)){assertEquals(3,store.count("materials",null,null));}}
 @Test public void changingBookProgressUpdatesTheSameCourseMaterial()throws Exception{long id=material("Leitura partilhada",20);b.show();drain();b.setProgress(b.books.get(0),100);drain();drain();try(StudyStore store=new StudyStore(a)){assertEquals(100,store.get("materials",id).n("progress"));assertEquals("Concluído",store.get("materials",id).s("status"));}}
 @Test public void importIsMultiDocumentPicker()throws Exception{a.studies=new StudyHub(a);try{b.pickFiles(BookImport.mimes(new HashSet<>(Arrays.asList("pdf","epub","docx","txt"))));Intent picker=shadowOf(a).getNextStartedActivity();assertTrue(Arrays.asList(picker.getStringArrayExtra(Intent.EXTRA_MIME_TYPES)).contains("application/pdf"));assertEquals(Intent.ACTION_OPEN_DOCUMENT,picker.getAction());assertTrue(picker.getBooleanExtra(Intent.EXTRA_ALLOW_MULTIPLE,false));assertEquals(0,a.studies.prefs.getLong("import_subject",-1));PackageInfo installed=new PackageInfo();installed.packageName="com.microsoft.emmx";installed.applicationInfo=new ApplicationInfo();installed.applicationInfo.packageName=installed.packageName;shadowOf(a.getPackageManager()).installPackage(installed);}finally{a.studies.close();}}
 @Test public void booksMountInMainNavigationWithEnglishLabels()throws Exception{a.prefs.edit().putString("language","en").apply();material("Book",80);a.render();drain();assertTrue(labels(a.shell).contains("All books"));assertTrue(labels(a.shell).contains("Haidoy Carlos Mautempo"));assertTrue(labels(a.shell).contains("More"));}
 static String labels(View view){String result=view instanceof TextView?((TextView)view).getText().toString():"";if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)result+="\n"+labels(group.getChildAt(i));}return result;}
 @Test public void filterPanelAndBookMenuMountOnSmallPhone()throws Exception{material("Um livro",38);b.show();drain();b.filters();assertNotNull(ShadowDialog.getLatestDialog());ShadowDialog.getLatestDialog().dismiss();b.bookMenu(b.books.get(0));assertNotNull(ShadowDialog.getLatestDialog());}
 static View clickable(View v){while(v!=null&&!v.hasOnClickListeners())v=v.getParent() instanceof View?(View)v.getParent():null;assertNotNull(v);return v;}
 @Test public void studyHomeOpensInternalSeekyAssistant()throws Exception{a.tab="Estudos";a.studies=new StudyHub(a);try{a.studies.show();for(int n=0;n<3;n++){a.studies.worker.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}View button=VoiceToolsTest.findText(a.body,"Estudar com Seeky");assertNotNull(button);button.performClick();shadowOf(Looper.getMainLooper()).idle();UiPanel panel=UiPanel.open.get(a).iterator().next();View root=panel.dialog.getWindow().getDecorView();String options=labels(root);assertTrue(options,options.contains("Conversa de estudo")&&options.contains("Perguntar a vários materiais")&&options.contains("Plano de estudo a partir de um tema")&&options.contains("Resumir um livro inteiro"));clickable(VoiceToolsTest.findText(root,"Conversa de estudo")).performClick();shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(2));Intent launch=shadowOf(a).getNextStartedActivity();assertEquals(StudyAssistantActivity.class.getName(),launch.getComponent().getClassName());assertNull(launch.getAction());assertFalse(launch.getBooleanExtra("many",false));button.performClick();shadowOf(Looper.getMainLooper()).idle();UiPanel second=null;for(UiPanel p:UiPanel.open.get(a))if(p!=panel)second=p;if(second==null)second=UiPanel.open.get(a).iterator().next();clickable(VoiceToolsTest.findText(second.dialog.getWindow().getDecorView(),"Perguntar a vários materiais")).performClick();shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(2));Intent many=shadowOf(a).getNextStartedActivity();assertEquals(StudyAssistantActivity.class.getName(),many.getComponent().getClassName());assertTrue(many.getBooleanExtra("many",false));}finally{a.studies.close();}}
 @Test public void readingButtonsHaveVisibleGapsAndDeleteCanBeCancelledOrConfirmed()throws Exception{a.prefs.edit().putString("theme","Escuro").apply();a.colors();long id=material("Leitura natural",38);b.show();drain();b.bookMenu(b.books.get(0));UiPanel panel=UiPanel.open.get(a).iterator().next();panel.root.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(640,View.MeasureSpec.EXACTLY));panel.root.layout(0,0,320,640);View read=VoiceToolsTest.findText(panel.root,"Ler"),listen=VoiceToolsTest.findText(panel.root,"Ouvir"),favorite=VoiceToolsTest.findText(panel.root,"Marcar como favorito");assertNotNull(read);assertTrue(listen.getLeft()-read.getRight()>=a.dp(10));View pair=(View)read.getParent(),favoriteRow=(View)favorite.getParent().getParent();assertTrue(favoriteRow.getTop()-pair.getBottom()>=a.dp(10));Bitmap image=Bitmap.createBitmap(320,640,Bitmap.Config.ARGB_8888);panel.root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-book-actions.png")){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();View remove=VoiceToolsTest.findText(panel.root,"Eliminar");assertNotNull(remove);remove.performClick();((UiDialog)ShadowDialog.getLatestDialog()).getButton(-2).performClick();try(StudyStore store=new StudyStore(a)){assertNotNull(store.get("materials",id));}b.bookMenu(b.books.get(0));panel=UiPanel.open.get(a).iterator().next();VoiceToolsTest.findText(panel.root,"Eliminar").performClick();((UiDialog)ShadowDialog.getLatestDialog()).getButton(-1).performClick();drain();drain();try(StudyStore store=new StudyStore(a)){assertNull(store.get("materials",id));}}
 static int count(View view,Class<?> type){int count=type.isInstance(view)?1:0;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)count+=count(group.getChildAt(i),type);}return count;}
 @Test public void coverSharesTheBookAsAReadOnlyContentUri()throws Exception{long id=material("Livro para partilhar",12);StudyStore.Row row;try(StudyStore db=new StudyStore(a)){row=db.get("materials",id);}b.bookMenu(row);UiPanel panel=UiPanel.open.get(a).iterator().next();View share=VoiceToolsTest.findText(panel.root,"Partilhar livro");assertNotNull(share);View click=share;while(!click.isClickable()&&click.getParent() instanceof View)click=(View)click.getParent();assertTrue(click.performClick());Intent chooser=shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_CHOOSER,chooser.getAction());Intent sent=chooser.getParcelableExtra(Intent.EXTRA_INTENT);assertEquals(Intent.ACTION_SEND,sent.getAction());Uri uri=sent.getParcelableExtra(Intent.EXTRA_STREAM);assertEquals("content",uri.getScheme());assertEquals(a.getPackageName()+".study",uri.getAuthority());assertEquals("text/plain",sent.getType());assertTrue((sent.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,sent.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);assertEquals(uri,sent.getClipData().getItemAt(0).getUri());}
}
